CREATE TABLE public.conversion_events (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),lead_id uuid references public.leads(id),student_id uuid references public.alunos(id),campaign_id uuid references public.campanhas_marketing(id),event_type text not null check(event_type in ('lead_created','contacted','experimental_booked','proposal_sent','subscription_started','payment_received','lost')),value_amount numeric,occurred_at timestamptz not null default now(),recorded_by uuid not null references auth.users(id),metadata jsonb not null default '{}'::jsonb);
ALTER TABLE public.conversion_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversion_events_org_access ON public.conversion_events FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=conversion_events.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager'))) WITH CHECK(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=conversion_events.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager')));
CREATE TABLE public.conversion_actions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),title text not null,reason text not null,status text not null default 'pending' check(status in ('pending','approved','dismissed','completed')),created_by uuid not null references auth.users(id),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
ALTER TABLE public.conversion_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversion_actions_org_access ON public.conversion_actions FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=conversion_actions.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager'))) WITH CHECK(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=conversion_actions.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager')));
CREATE OR REPLACE FUNCTION public.review_conversion_action(p_action_id uuid,p_status text) RETURNS public.conversion_actions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.conversion_actions; BEGIN SELECT * INTO v FROM public.conversion_actions WHERE id=p_action_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR NOT(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=v.organization_id AND m.user_id=auth.uid() AND m.papel::text IN('admin','manager'))) OR p_status NOT IN('approved','dismissed','completed') THEN RAISE EXCEPTION 'Ação inválida ou sem permissão'; END IF; UPDATE public.conversion_actions SET status=p_status,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=v.id RETURNING * INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.review_conversion_action(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_conversion_action(uuid,text) TO authenticated;

